export type mapaTileResponse200 = {
  data: Blob
  status: 200
}

export type mapaTileResponseSuccess = (mapaTileResponse200) & {
  headers: Headers;
};
;

export type mapaTileResponse = (mapaTileResponseSuccess)

export const getMapaTileUrl = (camada: string,
    z: number,
    x: number,
    y: number,
    params?: MapaTileParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `/api/v1/mapa/tiles/${camada}/${z}/${x}/${y}?${stringifiedParams}` : `/api/v1/mapa/tiles/${camada}/${z}/${x}/${y}`
}

/**
 * Vector tile (MVT) da camada, restrito ao escopo do usuário.
 *
 * Abaixo do zoom 16, os pontos são agrupados em células com a contagem
 * (``quantidade``); a partir dele, cada registro vira uma feição. Só as árvores, abaixo do zoom
 * 12, vêm agrupadas por bairro, com a contagem, a pior condição e o nome do bairro.
 */
export const mapaTile = async (camada: string,
    z: number,
    x: number,
    y: number,
    params?: MapaTileParams, options?: Parameters<typeof requisicao>[1]): Promise<mapaTileResponse> => {

  return requisicao<mapaTileResponse>(getMapaTileUrl(camada,z,x,y,params),
  {
    ...options,
    method: 'GET'


  }
);}





export const getMapaTileQueryKey = (camada: string,
    z: number,
    x: number,
    y: number,
    params?: MapaTileParams,) => {
    return [
    `/api/v1/mapa/tiles/${camada}/${z}/${x}/${y}`, ...(params ? [params] : [])
    ] as const;
    }


